'use client';

import * as React from "react";
import { useQuery } from "@tanstack/react-query";
import { googleNewsApi } from "@/lib/api/googleNews";
import { TokenCard } from "@/components/feed/TokenCard";
import { FilterBar } from "@/components/feed/FilterBar";
import { Skeleton } from "@/components/ui/skeleton";
import { motion } from "framer-motion";

export function FeedContainer() {
    const { data: items, isLoading, error } = useQuery({
        queryKey: ['topNews'],
        queryFn: () => googleNewsApi.fetchTop(),
    });

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[50vh] p-4 text-center">
                <p className="text-muted-foreground mb-4">Unable to load feed. The API key might be missing or exhausted.</p>
                <button onClick={() => window.location.reload()} className="text-primary hover:underline">Retry</button>
            </div>
        )
    }

    return (
        <div className="flex flex-col min-h-screen bg-background items-center">
            <FilterBar className="w-full max-w-lg" />

            <div className="w-full max-w-lg px-4 pt-4 pb-20 space-y-6">
                {isLoading ? (
                    // Skeleton Loading State
                    Array.from({ length: 3 }).map((_, i) => (
                        <div key={i} className="space-y-3 p-5 border border-border/40 rounded-2xl bg-card">
                            <div className="flex items-center gap-3">
                                <Skeleton className="h-6 w-6 rounded-full" />
                                <Skeleton className="h-3 w-24" />
                            </div>
                            <Skeleton className="h-6 w-3/4" />
                            <Skeleton className="h-20 w-full" />
                            <div className="flex gap-2 pt-2">
                                <Skeleton className="h-5 w-16 rounded-md" />
                                <Skeleton className="h-5 w-16 rounded-md" />
                            </div>
                        </div>
                    ))
                ) : (
                    items?.map((item, index) => (
                        <TokenCard key={item.id} item={item} priority={index === 0} />
                    ))
                )}

                {!isLoading && items && items.length > 0 && (
                    <div className="text-center py-8">
                        <p className="text-sm text-muted-foreground">You're all caught up!</p>
                    </div>
                )}
            </div>
        </div>
    );
}
